function M.enable(user_opts)
  M.setup(user_opts)
end

function M.run(raw_args)
  require("diff.core").run(raw_args or "")
end

function M.clear()
  require("diff.core").clear()
end

function M.diff_buffers(raw_args)
  require("diff.core").run_buffers(raw_args or "")
end

function M.diff_origin()
  require("diff.features.origin").run()
end

function M.exit()
  require("diff.features.exit").exit()
end

function M.register_global(cfg)
  if cfg.scope ~= "global" or type(cfg.key) ~= "string" or cfg.key == "" then
    return
  end
  map("n", cfg.key, require("diff.features.exit").exit, {
    silent = true,
  }, "[diff] Exit diff mode when active")
end

local function kv(key)
  return { key = key, type = "STRING", values = VALUE_LISTS[key] }
end

