local function prompt_file(callback)
  require("lib.nvim.ui.kit").input({
    title = "File path: ",
    completion = "file",
    on_submit = function(path)
      callback(path ~= "" and path or nil)
    end,
    on_cancel = function()
      callback(nil)
    end,
  })
end

local function pick_specifier(kind, callback)
  local select_fn = resolve_configured_select_fn() or kit_confirm_select

  local choices, handlers
  if kind == "source" then
    choices = { CHOICE_CURRENT, CHOICE_CLIPBOARD, CHOICE_FILE, CHOICE_BUFFER }
    handlers = {
      function(cb)
        cb("current")
      end,
      function(cb)
        cb("clipboard")
      end,
      prompt_file,
      prompt_buffer,
    }
  else
    choices = { CHOICE_CLIPBOARD, CHOICE_FILE, CHOICE_BUFFER }
    handlers = {
      function(cb)
        cb("clipboard")
      end,
      prompt_file,
      prompt_buffer,
    }
  end

  select_fn(choices, { prompt = "Diff " .. kind .. ":" }, function(choice, idx)
    if not choice or not idx or not handlers[idx] then
      callback(nil)
      return
    end
    handlers[idx](callback)
  end)
end

function M.valid_lists()
  return VALID_VIEWS, VALID_OUTPUTS
end

function M.is_git_spec(spec)
  return type(spec) == "string" and spec:sub(1, 4) == "git:"
end

function M.compute_unified(a_lines, b_lines, algorithm, ctxlen)
  local ok, result = pcall(
    vim.diff,
    table.concat(a_lines, "\n") .. "\n",
    table.concat(b_lines, "\n") .. "\n",
    { result_type = "unified", algorithm = algorithm, ctxlen = ctxlen }
  )
  if not ok or type(result) ~= "string" then
    return nil, "vim.diff failed: " .. tostring(result)
  end
  return result, nil
end

function M.format_stats(stats)
  return string.format(
    "+%d -%d, %d hunk%s",
    stats.added,
    stats.removed,
    stats.hunks,
    (stats.hunks == 1) and "" or "s"
  )
end
